function isPalindrome(str) {
    let reversedStr = str.split('').reverse().join('');
    return str === reversedStr;
}

console.log(isPalindrome("A man, a plan, a canal: Panama")); // true
console.log(isPalindrome("Not a palindrome")); // false
```

This function works by first reversing the input string `str` using the `reverse()` method on each character in the string. Then it checks if the reversed string is equal to its reverse. If they are, then the original string is a palindrome.

Alternatively, you can use a more concise version:

```javascript
function isPalindrome(str) {
    return str === str.split('').reverse().join('');
}

console.log(isPalindrome("A man, a plan, a canal: Panama")); // true
console.log(isPalindrome("Not a palindrome")); // false
```

