function fizzBuzz(n) {
    let result = "";

    for (let i = 1; i <= Math.floor(Math.sqrt(n)) + 2; i++) {
        if (i % 3 == 0 && i % 5 == 0)
            result += "FizzBuzz";

        else if (i % 3 == 0 || i % 5 == 0)
            result += "Fizz";

        else if (i % 2 == 0)
            result += "Buzz";
    }

    return result;
}
```

