function uniqueSorted(arr) {
    let result = [];

    for (let i = 0; i < arr.length; i++) {
        if (!result[i]) {
            result[i] = [...arr];
        } else if (arr[i].indexOf(arr[i]) > -1 && !result[i].includes(arr[i])) {
            result[i] = arr.slice();
