function recursiveListSum(arr) {
    // Base case: if the array is empty, return 0
    if (arr.length === 0) {
        return 0;
    }

    // Recursive case: sum the first element and then call recursively on the rest of the array
    const firstElement = arr[0];
    const remainingArray = arr.slice(1);
    return firstElement + recursiveListSum(remainingArray);
}
